import{_ as l,l as n,o as e,c as r,v as s,p as o,x as t,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"Hessian 感知量化","description":"","frontmatter":{"title":"Hessian 感知量化","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/hessian-aware-quant.md","filePath":"llm/hessian-aware-quant.md","lastUpdated":1789023840000}'),H={name:"llm/hessian-aware-quant.md"};function m(T,a,_,u,E,c){const i=n("Mermaid");return e(),r("div",null,[a[1]||(a[1]=s('<h1 id="hessian-感知量化" tabindex="-1">Hessian 感知量化 <a class="header-anchor" href="#hessian-感知量化" aria-label="Permalink to &quot;Hessian 感知量化&quot;">​</a></h1><div class="epigraph"><p>损失对参数的二阶告诉你：同样一步台阶，打在高曲率方向上更疼。量化顺序与补偿应沿着 Hessian，而不是沿着 $|w|$。</p><footer>—— 对照 HAWQ 一类 Hessian 感知混合精度；LLM 规模的可用实例是 GPTQ</footer></div><p><a href="/llm/adaround">AdaRound</a> 在格子上选上或下。<a href="/llm/gptq">GPTQ</a> 主课已经把 OBQ 的二阶补偿做成可跑完 175B 的算法。本课补的是 <strong>课序缺口</strong>：为何二阶出现、HAWQ 如何用 Hessian 分配 bit、以及不要把「Hessian 感知」当成又一篇独立配方去重导 GPTQ。后课混精搜索会用到「层的敏感度」这一标量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一阶（梯度）在训练末期接近零，对「哪一个权重更怕量化」几乎没信号。二阶 \\(H\\approx \\partial^2 L/\\partial w^2\\) 描述损失曲面的曲率：大特征值方向上，离散化同一 \\(\\Delta w\\) 引起的 \\(\\Delta L\\) 更大。幅度剪枝与 RTN 都忽略这一点，于是删/量化了「权小、曲率大」的连接——激活大时正是这些。</p><p>全模型 Hessian 不可存。层内用 \\(\\|WX-\\hat WX\\|^2\\) 时，\\(H\\) 与 \\(XX^\\top\\) 成正比，这就是 GPTQ 用校准激活代替损失 Hessian 的理由。HAWQ 一类工作则用 Hessian 谱给不同层/块分配不同 bit。问题是 <strong>用哪一个 Hessian、在哪一层近似</strong>，不是「算真·\\(\\nabla^2 L\\)」。</p><p><span class="marginnote">OBQ / OBS 来自最优脑损伤传统：用二阶估计删掉某个权重的损失增量。GPTQ 把它从「每步搜最不疼的那个」改成固定列序，否则 LLM 跑不完。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三条落地，由轻到重：</p><ol><li>层敏感度：用 Hessian 迹或最大特征值给层打分，敏感层留 8 bit，其余 4 bit——混精搜索的启发式，下一课。</li><li>层内重建：GPTQ 按列量化并用 \\(H^{-1}\\) 补偿剩余列。细节不重复，链到主课。</li><li>与 AdaRound 结合：二阶告诉补偿，舍入告诉离散点；工程上常只做 GPTQ。</li></ol><p>校准 \\(X\\) 质量决定 \\(H\\) 质量。阻尼 \\(\\lambda I\\) 防病态，过大则退化成 RTN。</p>',11)),(e(),o(h,null,{default:t(()=>[p(i,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%A0%A1%E5%87%86%E6%BF%80%E6%B4%BB%22%5D%20--%3E%20H%5B%22H%20~%20XX%5ET%22%5D%0A%20%20H%20--%3E%20SENS%5B%22%E5%B1%82%E6%95%8F%E6%84%9F%E5%BA%A6%20-%3E%20%E6%B7%B7%E7%B2%BE%22%5D%0A%20%20H%20--%3E%20CMP%5B%22%E5%88%97%E8%A1%A5%E5%81%BF%20-%3E%20GPTQ%22%5D%0A%20%20H%20--%3E%20DAMP%5B%22%E9%98%BB%E5%B0%BC%E9%98%B2%E7%97%85%E6%80%81%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>二次型 \\((w-\\hat w)^\\top H (w-\\hat w)\\)：在 \\(H\\) 的主轴上误差被放大。独立 RTN 在这些轴上的投影是相干的。补偿 = 在未量化子空间做牛顿步减小同一二次型。因此 Hessian 感知不是「更平滑的 round」，而是 <strong>把离散化当约束的二次优化</strong>。</p><p>层间：真损失 Hessian 有跨层耦合。逐层 \\(XX^\\top\\) 忽略耦合，所以前层量化后必须用新激活校准后层。这是近似的边界，也是必须逐层真实路径前向的原因。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要每步用自动微分估全模型 Hessian。不要把 HAWQ 的层 bit 分配直接抄到 Transformer 而不重测——注意力与 MLP 的谱不同。不要认为 2-bit 在二阶补偿下仍自由：网格本身的不可补偿分量会占主导，见 GPTQ 主课。下一课把敏感度变成搜索：混合精度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>二阶刻画「哪一方向怕量化」；幅度与 RTN 看不见它。</li><li>层内 \\(H\\sim XX^\\top\\)，GPTQ 是可扩展的补偿算法。</li><li>层间用迹 / 特征值做 bit 分配启发式。</li><li>校准与阻尼决定 \\(H\\) 是信号还是退化成 RTN。</li><li>出处：HAWQ；OBQ；GPTQ（ICLR 2023）作为 LLM 实例。</li></ul>',7))])}const P=l(H,[["render",m]]);export{A as __pageData,P as default};
